import{_ as r,B as s,o as l,c,a8 as d,a,E as t,f as i}from"./chunks/framework.CNIpabDg.js";const y=JSON.parse('{"title":"Bootsplash","description":"The bootsplash crate provides a focused startup animation layer around the graphics manager and LVGL objects.","frontmatter":{"layout":"doc","docType":"explanation","description":"The bootsplash crate provides a focused startup animation layer around the graphics manager and LVGL objects."},"headers":[],"relativePath":"explanation/architecture/libraries/bootsplash.md","filePath":"explanation/architecture/libraries/bootsplash.md","lastUpdated":1792488559000}'),h={name:"explanation/architecture/libraries/bootsplash.md"};function p(u,e,m,g,b,k){const o=s("CodeReference"),n=s("HostReference");return l(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792488559000"},[e[4]||(e[4]=d(`<h1 id="bootsplash" tabindex="-1">Bootsplash <a class="header-anchor" href="#bootsplash" aria-label="Permalink to &quot;Bootsplash&quot;">​</a></h1><p>The <code>bootsplash</code> crate provides a focused startup animation layer around the graphics manager and LVGL objects.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><ul><li>Owns creation and teardown of the boot logo animation sequence.</li><li>Encapsulates the startup-only animation policy so initialization code does not manipulate LVGL animation internals directly.</li></ul><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>In scope: logo object setup, animation callback wiring, animation lifetime management.</li><li>Out of scope: window/session management, general UI composition, or reusable animation framework APIs.</li></ul><h2 id="internal-structure" tabindex="-1">Internal structure <a class="header-anchor" href="#internal-structure" aria-label="Permalink to &quot;Internal structure&quot;">​</a></h2><ul><li><code>lib.rs</code>: <code>Bootsplash</code> state (<code>lv_anim_t</code> + <code>Logo</code>) and lifecycle methods.</li><li><code>error.rs</code>: crate-local error type mapped from graphics failures.</li><li>One <code>unsafe extern &quot;C&quot;</code> callback (<code>load_animation_callback</code>) updates part opacity across logo children.</li></ul><h2 id="runtime-interaction" tabindex="-1">Runtime interaction <a class="header-anchor" href="#runtime-interaction" aria-label="Permalink to &quot;Runtime interaction&quot;">​</a></h2><ol><li><code>Bootsplash::new</code> acquires <code>graphics::Manager</code> lock.</li><li>It uses current screen geometry to compute <code>Logo::get_factor(...)</code> and instantiate logo.</li><li>It initializes <code>lv_anim_t</code> (<code>duration</code>, reverse timing, repeat count) and registers callback.</li><li><code>Bootsplash::stop</code> deletes the animation via <code>lv_anim_delete</code> under manager lock.</li></ol><h2 id="dependency-model" tabindex="-1">Dependency model <a class="header-anchor" href="#dependency-model" aria-label="Permalink to &quot;Dependency model&quot;">​</a></h2><ul><li>Internal runtime dependency: <a href="/explanation/architecture/subsystems/graphics.html">Graphics</a> only.</li><li>Uses LVGL symbols re-exported through graphics (<code>lv_anim_*</code>, <code>lv_obj_*</code>).</li></ul><h2 id="failure-semantics" tabindex="-1">Failure semantics <a class="header-anchor" href="#failure-semantics" aria-label="Permalink to &quot;Failure semantics&quot;">​</a></h2><ul><li>Setup failures propagate as crate <code>Error</code> during <code>new</code>.</li><li><code>stop</code> can fail through graphics lock/manager-level error propagation.</li></ul><h2 id="extension-points" tabindex="-1">Extension points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension points&quot;">​</a></h2><ul><li>Animation timing/profile can be changed centrally in <code>Bootsplash::new</code>.</li><li>Alternate startup visuals can reuse the same lifecycle contract (<code>new</code>/<code>stop</code>) while changing object composition.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: construct bootsplash with <code>Bootsplash::new(...)</code>, stop it with <code>Bootsplash::stop(...)</code>.</li><li><strong>Current implementation</strong>: LVGL opacity animation over 4 logo parts using theme primary color and ease-in-out path.</li></ul><h2 id="limitations-and-trade-offs" tabindex="-1">Limitations and trade-offs <a class="header-anchor" href="#limitations-and-trade-offs" aria-label="Permalink to &quot;Limitations and trade-offs&quot;">​</a></h2><ul><li>Uses <code>std::os::raw::c_void</code> and LVGL callback ABI, so the implementation is intentionally low-level.</li><li>Animation is tightly tied to current logo part layout and not exposed as a generic animation graph.</li></ul><h2 id="construction-animation-and-teardown" tabindex="-1">Construction, animation and teardown <a class="header-anchor" href="#construction-animation-and-teardown" aria-label="Permalink to &quot;Construction, animation and teardown&quot;">​</a></h2><p><code>Bootsplash::new(graphics_manager: &amp;&#39;static graphics::Manager).await</code> obtains the Graphics lock, reads the active LVGL screen size, scales the logo to <strong>30%</strong> of the current screen dimension and picks its foreground from the screen&#39;s main text color. It constructs a <code>Logo</code> and starts a repeating LVGL opacity animation.</p><p>The current animation uses values 64–255, <strong>500 ms forward and 500 ms reverse</strong>, an ease-in/out callback and an effectively indefinite repeat count. The callback cycles the four logo parts. Those exact values are design parameters, not part of the general Graphics contract.</p><p><code>Bootsplash::stop(self, graphics_manager).await</code> consumes the splash, takes the Graphics lock, deletes the matching animation callback/variable pair and then lets Rust drop the logo. <strong>Call <code>stop</code> explicitly</strong> before releasing the logo or ending the graphics runtime: simply dropping an active splash does not execute the animation-deletion path shown in <code>stop</code>.</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> splash </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bootsplash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Bootsplash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(graphics_manager)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.await?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Continue initializing the runtime while the graphics loop renders.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">splash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(graphics_manager)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.await?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The example assumes the Graphics service is running and <code>graphics_manager</code> has a <code>&#39;static</code> lifetime. An initialized screen and progressing LVGL timer handler are prerequisites for visible animation.</p><h2 id="ownership-and-portability-caveats" tabindex="-1">Ownership and portability caveats <a class="header-anchor" href="#ownership-and-portability-caveats" aria-label="Permalink to &quot;Ownership and portability caveats&quot;">​</a></h2><p>The library owns a boxed <code>lv_anim_t</code> and a Graphics <code>Logo</code>, but the animation is registered through an unsafe C callback and a static mutable animation-part index. It is therefore <strong>not a reentrant generic animation component</strong>: multiple concurrent splashes and arbitrary LVGL lifecycle resets require care. Its <code>std::os::raw::c_void</code> import means the implementation is not universally <code>no_std</code> even though many Xila libraries are.</p>`,28)),a("ul",null,[a("li",null,[t(o,{path:"libraries/bootsplash/src/lib.rs"}),e[0]||(e[0]=i(" — actual animation and stop sequence.",-1))]),a("li",null,[t(n,{crate:"bootsplash",kind:"struct",symbol:"Bootsplash"}),e[1]||(e[1]=i(" — construction/teardown API.",-1))])]),e[5]||(e[5]=a("h2",{id:"references",tabindex:"-1"},[i("References "),a("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),a("ul",null,[a("li",null,[t(n,{crate:"bootsplash"}),e[2]||(e[2]=i(" — generated Rust API documentation.",-1))]),a("li",null,[t(o,{path:"libraries/bootsplash"})]),e[3]||(e[3]=a("li",null,[a("p",null,[a("a",{href:"/explanation/architecture/subsystems/graphics.html"},"Graphics")])],-1))])])}const v=r(h,[["render",p]]);export{y as __pageData,v as default};
